CREATE TABLE token_accounts (user_id uuid PRIMARY KEY REFERENCES users(id), quota_total bigint NOT NULL DEFAULT 0 CHECK (quota_total >= 0), settled_total bigint NOT NULL DEFAULT 0 CHECK (settled_total >= 0), reserved_total bigint NOT NULL DEFAULT 0 CHECK (reserved_total >= 0), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO token_accounts(user_id) SELECT id FROM users ON CONFLICT DO NOTHING;
CREATE TABLE token_requests (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), model text NOT NULL, reserved_tokens bigint NOT NULL CHECK (reserved_tokens >= 0), input_tokens bigint, output_tokens bigint, status text NOT NULL CHECK (status IN ('reserved','settled','pending_review','released')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX token_requests_user_status_idx ON token_requests(user_id,status,created_at DESC);
CREATE TABLE token_adjustments (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), actor_user_id uuid NOT NULL REFERENCES users(id), quota_before bigint NOT NULL, quota_after bigint NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
